def generate(rng):
    H=rng.randint(12,24); W=rng.randint(12,24)
    bg=rng.choice([0,6,7]); obj=rng.choice([2,3,5,9]); ray=rng.choice([1,4,8])
    g=[[bg]*W for _ in range(H)]
    h=rng.randint(2,5); w=rng.randint(2,6)
    r0=rng.randint(2,H-h-3); c0=rng.randint(2,W-w-3)
    for r in range(r0,r0+h):
        for c in range(c0,c0+w): g[r][c]=obj
    # aligned markers on some outside sides, plus distractors
    sides=list('ULRD'); rng.shuffle(sides)
    for side in sides[:rng.randint(1,3)]:
        if side=='U': r=rng.randint(0,r0-1); c=rng.randint(c0,c0+w-1)
        elif side=='D': r=rng.randint(r0+h,H-1); c=rng.randint(c0,c0+w-1)
        elif side=='L': r=rng.randint(r0,r0+h-1); c=rng.randint(0,c0-1)
